    /**
     * One viewport row as styled cells -- one call per row instead of
     * `cols` calls to `get_cell`, and it reads through the scrollback
     * offset set by `scroll_viewport_*`.
     */
    func viewportRow(row: UInt32)  -> [FfiCell]

}
