public struct FfiConverterTypeFfiCursorShape: FfiConverterRustBuffer {
    typealias SwiftType = FfiCursorShape

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> FfiCursorShape {
        let variant: Int32 = try readInt(&buf)
        switch variant {

        case 1: return .block

        case 2: return .underline

        case 3: return .bar

        default: throw UniffiInternalError.unexpectedEnumCase
        }
