        case 3: return .versionMismatch

        case 4: return .resized

        case 5: return .viewportScrolled

        case 6: return .screenSwitched

        case 7: return .reset

        case 8: return .fullDamage

        case 9: return .damageOwnershipLost

        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

