/**
 * The typed failures of the checkpoint API.
 *
 * A bool cannot tell "corrupt payload" from "valid payload of a version I
 * cannot read", and those two need different decisions from a peer: retry or
 * negotiate down versus fail explicitly.
 */
public
enum TakoCheckpointError: Swift.Error, Equatable, Hashable, Foundation.LocalizedError {



    case NullArgument
    case TooLarge(size: UInt64, limit: UInt64
    )
    case UnsupportedVersion(version: UInt32
    )
    case Corrupt(reason: String
    )






    public var errorDescription: String? {
        String(reflecting: self)
    }

}

#if compiler(>=6)
extension TakoCheckpointError: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeTakoCheckpointError: FfiConverterRustBuffer {
    typealias SwiftType = TakoCheckpointError

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> TakoCheckpointError {
        let variant: Int32 = try readInt(&buf)
        switch variant {




        case 1: return .NullArgument
        case 2: return .TooLarge(
            size: try FfiConverterUInt64.read(from: &buf),
            limit: try FfiConverterUInt64.read(from: &buf)
            )
        case 3: return .UnsupportedVersion(
            version: try FfiConverterUInt32.read(from: &buf)
            )
        case 4: return .Corrupt(
            reason: try FfiConverterString.read(from: &buf)
            )

         default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: TakoCheckpointError, into buf: inout [UInt8]) {
        switch value {





        case .NullArgument:
            writeInt(&buf, Int32(1))


        case let .TooLarge(size,limit):
            writeInt(&buf, Int32(2))
            FfiConverterUInt64.write(size, into: &buf)
            FfiConverterUInt64.write(limit, into: &buf)


        case let .UnsupportedVersion(version):
            writeInt(&buf, Int32(3))
            FfiConverterUInt32.write(version, into: &buf)


        case let .Corrupt(reason):
            writeInt(&buf, Int32(4))
            FfiConverterString.write(reason, into: &buf)

        }
    }
}


